	describe("A3: schemas reject invalid data", () => {
		// @lore U1: selectProductSchema removed. Use selectTeamSchema.
		it("selectTeamSchema rejects missing required fields (formerly selectProductSchema)", () => {
			const result = selectTeamSchema.safeParse({
				// missing id, name, phase, createdAt
				briefPath: null,
			});
			expect(result.success).toBe(false);
		});

		it("selectBetSchema rejects missing required fields", () => {
			const result = selectBetSchema.safeParse({
				// missing id, productId, teamId, pitch, status, createdAt
				appetite: null,
			});
			expect(result.success).toBe(false);
		});

		it("selectSessionSchema rejects missing required fields", () => {
			const result = selectSessionSchema.safeParse({
				// missing id, taskId, agentId, modelTier, startedAt, state
			});
			expect(result.success).toBe(false);
		});
	});

	describe("A4: schema field types match Drizzle column types", () => {
		// @lore U1: selectProductSchema removed. Use selectTeamSchema.
		it("selectTeamSchema id field is a string (formerly selectProductSchema)", () => {
			const shape = selectTeamSchema.shape;
			expect(shape).toBeDefined();
			// id column is text (string in Zod)
			const idResult = (
				shape as Record<string, { safeParse: (v: unknown) => { success: boolean } }>
			).id?.safeParse("some-id");
			expect(idResult?.success).toBe(true);
			const idBadResult = (
				shape as Record<string, { safeParse: (v: unknown) => { success: boolean } }>
			).id?.safeParse(123);
			expect(idBadResult?.success).toBe(false);
		});
	});
